  1	/**
  2	 * Parses a gated PLAN.md (create-validation-plan format) into a PlanModel.
  3	 *
  4	 * Recognised blocks (XML-ish tags):
  5	 *   <task id="1">…</task>
  6	 *   <validation_gate id="VG-1" blocking="true">…</validation_gate>
  7	 *   <regression_gate id="VG-REGRESS-01" blocking="true">…</regression_gate>
  8	 *   <phase_gate id="VG-PHASE-01" blocking="true">…</phase_gate>
  9	 *
 10	 * Inside a gate body the "Capture:" and "Pass criteria:" lines are extracted so the
 11	 * runner can verify evidence files exist and show criteria in the evidence overlay.
 12	 */
 13	import { basename, dirname } from "node:path";
 14	import type { GateKind } from "../engine/events.js";
 15	
 16	export interface PlanTask {
 17	  id: string;
 18	  name: string;
 19	  body: string;
 20	}
 21	
 22	export interface PlanGate {
 23	  id: string;
 24	  kind: GateKind;
 25	  blocking: boolean;
 26	  body: string;
 27	  /** evidence file names / patterns mentioned on the Capture: line(s) */
 28	  capture: string[];
 29	  criteria: string;
 30	  afterTask?: string;
 31	}
 32	
 33	export interface PlanModel {
 34	  id: string; // "02-01"
 35	  phase: string; // "02-cutover"
 36	  file: string;
 37	  title: string;
 38	  platform?: string;
 39	  tasks: PlanTask[];
 40	  gates: PlanGate[];
 41	  sequence: Array<{ type: "task" | "gate"; id: string }>;
 42	  evidenceDirHint?: string;
 43	}
 44	
 45	const BLOCK_RE = /<(task|validation_gate|regression_gate|phase_gate)\b([^>]*)>([\s\S]*?)<\/\1>/g;
 46	
 47	function attr(attrs: string, name: string): string | undefined {
 48	  const m = new RegExp(`${name}\\s*=\\s*"([^"]*)"`).exec(attrs);
 49	  return m?.[1];
 50	}
 51	
 52	const FILE_EXT = /\.(txt|json|log|png|yml|yaml|md|har|diff|sqlite|plist)\b/;
 53	
 54	/** Extract evidence targets (`vg2-health.json`, `E/vg3-card.png`, `vg8-*.{txt,log}`) from a Capture line. */
 55	export function extractCaptureTargets(line: string): string[] {
 56	  const out = new Set<string>();
 57	  const backticks = [...line.matchAll(/`([^`]+)`/g)].map((m) => m[1].trim());
 58	  for (const raw of backticks) {
 59	    if (/\s/.test(raw) && !FILE_EXT.test(raw)) continue;
 60	    // split "a, b" inside one backtick pair
 61	    for (const piece of raw.split(/\s*,\s*/)) {
 62	      if (FILE_EXT.test(piece) || /vg[-\w*]*\.[\w.{},*]+/i.test(piece)) out.add(piece.replace(/^E\//, ""));
 63	    }
 64	  }
 65	  const bare = [...line.matchAll(/\b(?:E\/)?(vg[-\w*]*\.[\w.{},*]+)/gi)].map((m) => m[1]);
 66	  for (const b of bare) out.add(b);
 67	  return [...out];
 68	}
 69	
 70	export function parsePlan(markdown: string, file: string): PlanModel {
 71	  const name = basename(file).replace(/-PLAN\.md$/i, "");
 72	  const titleMatch = /^#\s+(.+)$/m.exec(markdown);
 73	  const platform = /^Platform:\s*([^\s·|]+)/m.exec(markdown)?.[1];
 74	  const evidenceDirHint = /E\s*=\s*`?([^`\s]+evidence\/?)`?/.exec(markdown)?.[1];
 75	  const phase = basename(dirname(file));
 76	
 77	  const tasks: PlanTask[] = [];
 78	  const gates: PlanGate[] = [];
 79	  const sequence: PlanModel["sequence"] = [];
 80	  let lastTaskId: string | undefined;
 81	
 82	  BLOCK_RE.lastIndex = 0;
 83	  let m: RegExpExecArray | null;
 84	  while ((m = BLOCK_RE.exec(markdown))) {
 85	    const [, tag, attrs, body] = m;
 86	    const id = attr(attrs, "id") ?? `${tag}-${sequence.length + 1}`;
 87	    if (tag === "task") {
 88	      const nameLine = /^\s*Name:\s*(.+)$/m.exec(body)?.[1]?.trim() ?? `Task ${id}`;
 89	      tasks.push({ id, name: nameLine, body: body.trim() });
 90	      sequence.push({ type: "task", id });
 91	      lastTaskId = id;
 92	      continue;
 93	    }
 94	    const kind: GateKind = tag === "validation_gate" ? "validation" : tag === "regression_gate" ? "regression" : "phase";
 95	    const captureLines = [...body.matchAll(/^\s*Capture:\s*(.+)$/gm)].map((x) => x[1]);
 96	    const capture = captureLines.flatMap(extractCaptureTargets);
 97	    const criteria =
 98	      /^\s*Pass criteria(?: \([^)]*\))?:\s*([\s\S]*?)(?=^\s*(?:Review|Verdict|Mock guard|Integration evidence):|\s*$)/m.exec(body)?.[1]?.trim() ?? "";
 99	    gates.push({ id, kind, blocking: (attr(attrs, "blocking") ?? "true") !== "false", body: body.trim(), capture, criteria, afterTask: kind === "validation" ? lastTaskId : undefined });
100	    sequence.push({ type: "gate", id });
101	  }
102	
103	  return { id: name, phase, file, title: titleMatch?.[1]?.trim() ?? name, platform, tasks, gates, sequence, evidenceDirHint };
104	}
105	
106	/** The contract Vigil appends to the plan so verdict lines are machine-detectable. */
107	export function runnerContract(plan: PlanModel, extra: { evidenceDir: string; planRoot: string }): string {
108	  const gateList = plan.gates.map((g) => g.id).join(", ");
109	  return [
110	    "",
111	    "---",
112	    "## Runner contract (Vigil)",
113	    `You are running plan ${plan.id} from ${plan.file}. Gates in order: ${gateList}.`,
114	    `Evidence directory for this plan: ${extra.evidenceDir} (create it if missing). Plan root: ${extra.planRoot}.`,
115	    "Every gate is BLOCKING. For each gate: perform its steps for real, save every Capture file, READ the evidence against the Pass criteria, then print exactly one line",
116	    "`VG-<id>: PASS` or `VG-<id>: FAIL <one-line reason>` using the gate's exact id (e.g. `VG-REGRESS-01: PASS`).",
117	    "Print `TASK <id>: DONE` when a task's Done condition is met.",
118	    "Never mock, stub, or fake a system to pass a gate. Never run `git stash`; never `git checkout`/`git switch` in the main checkout; never `pkill -f` or `killall` — kill by PID only. Run every command with NODE_ENV unset.",
119	    `If a gate FAILS: follow its Verdict line (rollback where it says so), write <evidence dir>/FAIL.md with what failed, and stop with \`PLAN ${plan.id}: FAIL\`.`,
120	    `When the last gate passes, finish with exactly \`PLAN ${plan.id}: PASS\`. Vigil writes the VALIDATION report itself — do not write *-VALIDATION.md.`,
121	  ].join("\n");
122	}
