 1	/** Detects verdict lines the runner contract asks the agent to print. */
 2	export type VerdictLine =
 3	  | { type: "gate"; gateId: string; verdict: "pass" | "fail"; reason?: string }
 4	  | { type: "task"; taskId: string }
 5	  | { type: "plan"; planId: string; verdict: "pass" | "fail" };
 6	
 7	const GATE_RE = /^\s*[`*_]*\s*(VG-[A-Z0-9-]+)\s*[`*_]*\s*:\s*[`*_]*\s*(PASS|FAIL)\b[`*_]*\s*(.*)$/i;
 8	const TASK_RE = /^\s*[`*_]*\s*TASK\s+([\w-]+)\s*[`*_]*\s*:\s*DONE\b/i;
 9	const PLAN_RE = /^\s*[`*_]*\s*PLAN\s+([\w-]+)\s*[`*_]*\s*:\s*[`*_]*\s*(PASS|FAIL)\b/i;
10	
11	export function parseVerdictLines(text: string): VerdictLine[] {
12	  const out: VerdictLine[] = [];
13	  for (const line of text.split(/\r?\n/)) {
14	    let m = PLAN_RE.exec(line);
15	    if (m) { out.push({ type: "plan", planId: m[1], verdict: m[2].toLowerCase() as "pass" | "fail" }); continue; }
16	    m = GATE_RE.exec(line);
17	    if (m) { out.push({ type: "gate", gateId: m[1].toUpperCase(), verdict: m[2].toLowerCase() as "pass" | "fail", reason: m[3]?.trim().replace(/^[\s\-\u2013\u2014:]+/, "") || undefined }); continue; }
18	    m = TASK_RE.exec(line);
19	    if (m) out.push({ type: "task", taskId: m[1] });
20	  }
21	  return out;
22	}
23	
24	/** Incremental line splitter for streamed text: returns complete lines, keeps the remainder. */
25	export class LineBuffer {
26	  private buf = "";
27	  push(chunk: string): string[] {
28	    this.buf += chunk;
29	    const parts = this.buf.split(/\r?\n/);
30	    this.buf = parts.pop() ?? "";
31	    return parts;
32	  }
33	  flush(): string[] {
34	    const rest = this.buf;
35	    this.buf = "";
36	    return rest ? [rest] : [];
37	  }
38	}
