 1	/**
 2	 * RunStore — everything a run observes goes to disk:
 3	 *   runs/<id>/events.jsonl   every RunEvent, one per line
 4	 *   runs/<id>/tools/<n>-<tool>.txt   full input + output per tool call
 5	 *   runs/<id>/gates.json     latest verdict + evidence per gate
 6	 *   runs/<id>/cost.json      per-plan and per-model usage
 7	 *   runs/<id>/session.json   SDK session ids per plan (for resume)
 8	 */
 9	import { mkdirSync, appendFileSync, writeFileSync, existsSync, readFileSync } from "node:fs";
10	import { join } from "node:path";
11	import type { RunEvent, Verdict } from "./events.js";
12	
13	export interface GateRecord { planId: string; gateId: string; verdict: Verdict; reason?: string; evidence: { path: string; present: boolean; bytes: number }[]; updatedAt: number; }
14	
15	export class RunStore {
16	  readonly dir: string;
17	  private toolSeq = 0;
18	  private toolFiles = new Map<string, string>();
19	  private streamed = new Set<string>();
20	  private gates: Record<string, GateRecord> = {};
21	  private sessions: Record<string, string> = {};
22	  private cost: Record<string, unknown> = {};
23	
24	  constructor(readonly runsRoot: string, readonly runId: string) {
25	    this.dir = join(runsRoot, runId);
26	    mkdirSync(join(this.dir, "tools"), { recursive: true });
27	  }
28	
29	  static newRunId(label: string): string {
30	    const ts = new Date().toISOString().replace(/[-:]/g, "").replace(/\.\d+Z$/, "Z");
31	    return `${ts}-${label.replace(/[^\w.-]+/g, "_").slice(0, 40)}`;
32	  }
33	
34	  append(ev: RunEvent): void {
35	    appendFileSync(join(this.dir, "events.jsonl"), JSON.stringify(ev) + "\n");
36	    switch (ev.kind) {
37	      case "tool.start": {
38	        const f = join(this.dir, "tools", `${String(++this.toolSeq).padStart(4, "0")}-${ev.name}.txt`);
39	        this.toolFiles.set(ev.toolUseId, f);
40	        writeFileSync(f, `# ${ev.name}  ${new Date(ev.t).toISOString()}  id=${ev.toolUseId}${ev.parentToolUseId ? `  parent=${ev.parentToolUseId}` : ""}\n## input\n${JSON.stringify(ev.input, null, 2)}\n## output\n`);
41	        break;
42	      }
43	      case "tool.output": { const f = this.toolFiles.get(ev.toolUseId); if (f) { appendFileSync(f, ev.chunk); this.streamed.add(ev.toolUseId); } break; }
44	      case "tool.end": { const f = this.toolFiles.get(ev.toolUseId); if (f) appendFileSync(f, `\n## end ok=${ev.ok} durationMs=${ev.durationMs}\n${this.streamed.has(ev.toolUseId) ? "" : ev.output.slice(-20000) + "\n"}`); this.streamed.delete(ev.toolUseId); break; }
45	      case "gate.update": {
46	        this.gates[`${ev.planId}/${ev.gateId}`] = { planId: ev.planId, gateId: ev.gateId, verdict: ev.verdict, reason: ev.reason, evidence: ev.evidence ?? [], updatedAt: ev.t };
47	        writeFileSync(join(this.dir, "gates.json"), JSON.stringify(this.gates, null, 2));
48	        break;
49	      }
50	      case "session.init": { this.sessions[ev.planId] = ev.sessionId; writeFileSync(join(this.dir, "session.json"), JSON.stringify(this.sessions, null, 2)); break; }
51	      case "session.result": { this.cost[ev.planId] = { costUsd: ev.costUsd, durationMs: ev.durationMs, turns: ev.turns, usage: ev.usage, modelUsage: ev.modelUsage }; writeFileSync(join(this.dir, "cost.json"), JSON.stringify(this.cost, null, 2)); break; }
52	    }
53	  }
54	
55	  gatesForPlan(planId: string): GateRecord[] { return Object.values(this.gates).filter((g) => g.planId === planId); }
56	
57	  static readEvents(dir: string): RunEvent[] {
58	    const f = join(dir, "events.jsonl");
59	    if (!existsSync(f)) return [];
60	    return readFileSync(f, "utf8").split("\n").filter(Boolean).map((l) => JSON.parse(l) as RunEvent);
61	  }
62	}
