  1	/**
  2	 * Runner — sequences plans (or a single prompt) through PlanSession, persists
  3	 * events via RunStore, writes VALIDATION reports and ROADMAP status.
  4	 * Emits: event(RunEvent), approval, gateApproval, done.
  5	 */
  6	import { EventEmitter } from "node:events";
  7	import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
  8	import { join, resolve, dirname } from "node:path";
  9	import { PlanSession, type ApprovalMode, type ApprovalRequest, type GateApproval } from "./session.js";
 10	import { RunStore } from "./store.js";
 11	import { now, type RunEvent } from "./events.js";
 12	import { parsePlan, runnerContract, type PlanModel } from "../plan/parser.js";
 13	import { discoverPlans, selectPlans, type PlanRef } from "../plan/discover.js";
 14	import { renderValidation, updateRoadmapStatus, validationPath } from "../plan/reports.js";
 15	import { startProbes, type ProbeDef } from "./probes.js";
 16	import type { VigilConfig } from "../config.js";
 17	import { buildEnv } from "../config.js";
 18	import { execFileSync } from "node:child_process";
 19	
 20	/** Default executable: explicit option → CLAUDE_CODE_EXECPATH → `claude` on PATH → undefined (SDK default). */
 21	export function resolveClaudeBin(explicit?: string): string | undefined {
 22	  if (explicit) return explicit;
 23	  if (process.env.CLAUDE_CODE_EXECPATH && existsSync(process.env.CLAUDE_CODE_EXECPATH)) return process.env.CLAUDE_CODE_EXECPATH;
 24	  try { const p = execFileSync(process.platform === "win32" ? "where" : "which", ["claude"], { encoding: "utf8" }).split(/\r?\n/)[0].trim(); if (p && existsSync(p)) return p; } catch { /* not on PATH */ }
 25	  return undefined;
 26	}
 27	
 28	export interface RunnerOpts {
 29	  config: VigilConfig;
 30	  mode: "plan" | "prompt";
 31	  target?: string; // plan dir or PLAN.md
 32	  prompt?: string;
 33	  from?: string; to?: string; only?: string;
 34	  cwd: string;
 35	  approvals: ApprovalMode;
 36	  label?: string;
 37	  resume?: string;
 38	  runsRoot?: string;
 39	  pathToClaudeCodeExecutable?: string;
 40	}
 41	
 42	export class Runner extends EventEmitter {
 43	  store!: RunStore;
 44	  session: PlanSession | null = null;
 45	  approvals: ApprovalMode;
 46	  private stopProbes: (() => void) | null = null;
 47	  private abort = false;
 48	  planRoot = "";
 49	  plans: PlanRef[] = [];
 50	  models = new Map<string, PlanModel>();
 51	  private rerunRequested = false;
 52	
 53	  constructor(readonly opts: RunnerOpts) { super(); this.approvals = opts.approvals; }
 54	
 55	  private emitEv(ev: RunEvent) { this.store.append(ev); this.emit("event", ev); }
 56	
 57	  requestStop() { this.abort = true; this.session?.close(); }
 58	  requestRerun() { this.rerunRequested = true; }
 59	
 60	  async start(): Promise<boolean> {
 61	    const cfg = this.opts.config;
 62	    let label = this.opts.label ?? "prompt";
 63	    if (this.opts.mode === "plan") {
 64	      const d = discoverPlans(this.opts.target!);
 65	      this.planRoot = d.root;
 66	      this.plans = selectPlans(d.plans, { from: this.opts.from, to: this.opts.to, only: this.opts.only });
 67	      label = this.opts.label ?? this.planRoot.split("/").filter(Boolean).pop() ?? "plan";
 68	      for (const p of this.plans) this.models.set(p.id, parsePlan(readFileSync(p.file, "utf8"), p.file));
 69	    }
 70	    const runsRoot = this.opts.runsRoot ?? (this.opts.mode === "plan" ? join(this.planRoot, "runs") : resolve(this.opts.cwd, ".vigil/runs"));
 71	    this.store = new RunStore(runsRoot, RunStore.newRunId(label));
 72	    this.emitEv({ t: now(), kind: "run.start", runId: this.store.runId, mode: this.opts.mode, label, model: cfg.model, baseUrl: cfg.baseUrl, cwd: this.opts.cwd });
 73	    this.emitEv({ t: now(), kind: "log", level: "info", source: "vigil", message: `run dir ${this.store.dir}` });
 74	    if (cfg.probes.length) this.stopProbes = startProbes(cfg.probes as ProbeDef[], (ev) => this.emitEv(ev));
 75	
 76	    let ok = true;
 77	    if (this.opts.mode === "prompt") {
 78	      const r = await this.runOne({ id: "prompt", prompt: this.opts.prompt!, plan: undefined });
 79	      ok = r.verdict === "pass";
 80	    } else {
 81	      for (let i = 0; i < this.plans.length && !this.abort; i++) {
 82	        const ref = this.plans[i];
 83	        const model = this.models.get(ref.id)!;
 84	        const evidenceDir = join(dirname(ref.file), "evidence");
 85	        mkdirSync(evidenceDir, { recursive: true });
 86	        const prompt = readFileSync(ref.file, "utf8") + "\n" + runnerContract(model, { evidenceDir, planRoot: this.planRoot });
 87	        const r = await this.runOne({ id: ref.id, prompt, plan: model, evidenceDir });
 88	        if (r.verdict !== "pass") {
 89	          ok = false;
 90	          this.writeReports(model, false);
 91	          if (this.rerunRequested && !this.abort) { this.rerunRequested = false; i--; continue; }
 92	          break;
 93	        }
 94	        if (model.gates.some((g) => g.kind === "phase")) this.writeReports(model, true);
 95	      }
 96	    }
 97	    this.stopProbes?.();
 98	    this.emitEv({ t: now(), kind: "run.end", runId: this.store.runId, ok, reason: this.abort ? "stopped by operator" : undefined });
 99	    this.emit("done", ok);
100	    return ok;
101	  }
102	
103	  /** Blocks until the operator asks to re-run or quit after a failure. */
104	  waitForDecision(): Promise<"rerun" | "quit"> {
105	    return new Promise((resolve) => { this.once("decision", resolve); });
106	  }
107	
108	  private async runOne(p: { id: string; prompt: string; plan?: PlanModel; evidenceDir?: string }) {
109	    const cfg = this.opts.config;
110	    const t0 = now();
111	    this.emitEv({ t: t0, kind: "plan.start", planId: p.id, file: p.plan?.file ?? "(prompt)", title: p.plan?.title ?? "prompt", gateIds: p.plan?.gates.map((g) => g.id) ?? [] });
112	    const session = new PlanSession({
113	      planId: p.id, plan: p.plan, prompt: p.prompt, cwd: this.opts.cwd, env: buildEnv(cfg), model: cfg.model, maxTurns: cfg.maxTurns, maxBudgetUsd: cfg.maxBudgetUsd,
114	      addDirs: cfg.addDirs, rails: cfg.rails, approvals: this.approvals, evidenceDir: p.evidenceDir, resumeSessionId: this.opts.resume, pathToClaudeCodeExecutable: resolveClaudeBin(this.opts.pathToClaudeCodeExecutable), settingSources: cfg.settingSources,
115	    });
116	    this.session = session;
117	    session.on("event", (ev: RunEvent) => this.emitEv(ev));
118	    session.on("approval", (req: ApprovalRequest) => this.emit("approval", req));
119	    session.on("gateApproval", (g: GateApproval) => this.emit("gateApproval", g));
120	    let result: { verdict: "pass" | "fail" | "halted"; reason?: string };
121	    try { result = await session.run(); } catch (e) { result = { verdict: "halted", reason: String((e as Error).message ?? e) }; }
122	    if (p.plan) for (const g of p.plan.gates) if (session.gateState.get(g.id) === "pending" && result.verdict !== "pass") { /* leave pending */ }
123	    this.emitEv({ t: now(), kind: "plan.end", planId: p.id, verdict: result.verdict, reason: result.reason, durationMs: now() - t0 });
124	    if (result.verdict !== "pass" && !this.abort) {
125	      const d = await this.waitForDecision();
126	      if (d === "rerun") this.rerunRequested = true; else this.abort = true;
127	    }
128	    this.session = null;
129	    return result;
130	  }
131	
132	  decide(d: "rerun" | "quit") { this.emit("decision", d); }
133	
134	  private writeReports(model: PlanModel, pass: boolean) {
135	    const phaseDir = dirname(model.file);
136	    const phaseGates = [...this.models.values()].filter((m) => m.phase === model.phase);
137	    const gates = phaseGates.flatMap((m) => this.store.gatesForPlan(m.id));
138	    const md = renderValidation(phaseGates, gates, { phase: model.phase, platform: model.platform, runId: this.store.runId, evidenceDir: `phases/${model.phase}/evidence` });
139	    const out = validationPath(phaseDir, model.phase);
140	    writeFileSync(out, md);
141	    const phaseNo = model.phase.split("-")[0];
142	    const roadmap = join(this.planRoot, "ROADMAP.md");
143	    const phaseGate = gates.find((g) => g.gateId.startsWith("VG-PHASE"));
144	    if (existsSync(roadmap)) updateRoadmapStatus(roadmap, phaseNo, pass ? "✓ Validated" : "✗ Failed", phaseGate ? `${phaseGate.gateId} ${phaseGate.verdict.toUpperCase()}` : `${model.id} ${pass ? "PASS" : "FAIL"}`, `runs/${this.store.runId}`);
145	    this.emitEv({ t: now(), kind: "log", level: "info", source: "vigil", message: `wrote ${out}${existsSync(roadmap) ? " · ROADMAP status updated" : ""}` });
146	  }
147	}
