  1	/**
  2	 * PlanSession — drives one Claude Agent SDK query() per plan (or prompt),
  3	 * in streaming-input mode so the TUI can inject instructions / interrupt,
  4	 * and turns the SDK message stream + hooks into RunEvents.
  5	 */
  6	import { query, type Options, type SDKMessage, type SDKUserMessage, type HookCallback, type CanUseTool, type PermissionMode, type Query } from "@anthropic-ai/claude-agent-sdk";
  7	import { existsSync, statSync, readdirSync } from "node:fs";
  8	import { join } from "node:path";
  9	import { EventEmitter } from "node:events";
 10	import type { RunEvent, Verdict, TokenUsage } from "./events.js";
 11	import { now } from "./events.js";
 12	import { evaluateRails, type Rail } from "./rails.js";
 13	import { parseVerdictLines, LineBuffer } from "../plan/verdict.js";
 14	import type { PlanModel, PlanGate } from "../plan/parser.js";
 15	
 16	export type ApprovalMode = "auto" | "gates" | "all";
 17	
 18	export interface SessionOpts {
 19	  planId: string; // "prompt" for prompt mode
 20	  plan?: PlanModel;
 21	  prompt: string;
 22	  cwd: string;
 23	  env: Record<string, string>;
 24	  model: string;
 25	  maxTurns: number;
 26	  maxBudgetUsd?: number;
 27	  addDirs: string[];
 28	  rails: Rail[];
 29	  approvals: ApprovalMode;
 30	  evidenceDir?: string;
 31	  resumeSessionId?: string;
 32	  pathToClaudeCodeExecutable?: string;
 33	  settingSources?: Array<"user" | "project" | "local">;
 34	}
