 59	  private log(level: "debug" | "info" | "warn" | "error", source: string, message: string) { this.emitEv({ t: now(), kind: "log", level, source, message }); }
 60	
 61	  // ---- control surface used by the TUI ----
 62	  inject(text: string) {
 63	    this.inbox.push({ type: "user", message: { role: "user", content: text }, parent_tool_use_id: null } as SDKUserMessage);
 64	    this.emitEv({ t: now(), kind: "control", action: "inject", detail: text });
 65	    this.wake?.();
 66	  }
 67	  async interrupt() { this.emitEv({ t: now(), kind: "control", action: "interrupt" }); await this.q?.interrupt(); }
 68	  async setPermissionMode(mode: PermissionMode) { this.emitEv({ t: now(), kind: "control", action: "mode", detail: mode }); await this.q?.setPermissionMode(mode); }
 69	  pause() { this.paused = true; this.emitEv({ t: now(), kind: "control", action: "pause" }); }
 70	  resume() { this.paused = false; this.emitEv({ t: now(), kind: "control", action: "resume" }); for (const w of this.pausedWaiters.splice(0)) w(); }
 71	  close() { this.closed = true; this.wake?.(); }
 72	  private async whenNotPaused() { if (!this.paused) return; await new Promise<void>((r) => this.pausedWaiters.push(r)); }
 73	
 74	  private async *input(): AsyncGenerator<SDKUserMessage> {
 75	    yield { type: "user", message: { role: "user", content: this.opts.prompt }, parent_tool_use_id: null } as SDKUserMessage;
 76	    while (!this.closed) {
 77	      if (this.inbox.length) { yield this.inbox.shift()!; continue; }
