 84	  private preToolUse: HookCallback = async (input) => {
 85	    const t0 = now();
 86	    const i = input as { tool_name: string; tool_input: unknown; tool_use_id: string; hook_event_name: "PreToolUse" };
 87	    await this.whenNotPaused();
 88	    const hits = evaluateRails(this.opts.rails, i.tool_name, i.tool_input);
 89	    const deny = hits.find((h) => h.action === "deny");
 90	    for (const h of hits.filter((h) => h.action === "warn")) this.emitEv({ t: now(), kind: "hook", planId: this.opts.planId, event: "PreToolUse", tool: i.tool_name, decision: "warn", reason: `${h.rail.id}: ${h.reason}`, latencyMs: now() - t0 });
 91	    if (deny) {
 92	      this.emitEv({ t: now(), kind: "hook", planId: this.opts.planId, event: "PreToolUse", tool: i.tool_name, decision: "deny", reason: `${deny.rail.id}: ${deny.reason}`, latencyMs: now() - t0 });
 93	      return { hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "deny", permissionDecisionReason: `Vigil rail ${deny.rail.id}: ${deny.reason}` } };
 94	    }
 95	    this.emitEv({ t: now(), kind: "hook", planId: this.opts.planId, event: "PreToolUse", tool: i.tool_name, decision: "allow", latencyMs: now() - t0 });
 96	    return {};
 97	  };
 98	
 99	  private postToolUse: HookCallback = async (input) => {
100	    const i = input as { tool_name: string; tool_use_id: string; tool_response: unknown };
101	    this.emitEv({ t: now(), kind: "hook", planId: this.opts.planId, event: "PostToolUse", tool: i.tool_name, decision: "observe", latencyMs: 0 });
102	    return {};
103	  };
104	
105	  private canUseTool: CanUseTool = async (toolName, input) => {
106	    if (this.opts.approvals !== "all") return { behavior: "allow", updatedInput: input };
107	    const requestId = `${now()}-${Math.random().toString(36).slice(2, 8)}`;
108	    this.emitEv({ t: now(), kind: "approval.request", planId: this.opts.planId, requestId, tool: toolName, input });
109	    const allow = await new Promise<boolean>((resolve) => {
110	      const req: ApprovalRequest = { requestId, tool: toolName, input, resolve: (a) => resolve(a) };
111	      this.emit("approval", req);
112	    });
113	    this.emitEv({ t: now(), kind: "approval.resolve", planId: this.opts.planId, requestId, behavior: allow ? "allow" : "deny", by: "user" });
114	    return allow ? { behavior: "allow", updatedInput: input } : { behavior: "deny", message: "Denied by operator in Vigil" };
115	  };
116	
117	  // ---- evidence check ----
118	  private checkEvidence(gate: PlanGate): { path: string; present: boolean; bytes: number }[] {
119	    const dir = this.opts.evidenceDir;
120	    if (!dir) return [];
121	    let listing: string[] = [];
122	    try { listing = existsSync(dir) ? readdirSync(dir) : []; } catch { listing = []; }
123	    return gate.capture.map((pat) => {
124	      if (/[*{]/.test(pat)) {
125	        const re = new RegExp("^" + pat.replace(/[.+?^$()|[\]\\]/g, "\\$&").replace(/\{([^}]+)\}/g, (_, a) => `(${a.split(",").join("|")})`).replace(/\*/g, ".*") + "$");
126	        const matches = listing.filter((f) => re.test(f));
127	        const bytes = matches.reduce((n, f) => n + safeSize(join(dir, f)), 0);
128	        return { path: pat, present: matches.length > 0 && bytes > 0, bytes };
129	      }
130	      const p = join(dir, pat);
131	      const bytes = safeSize(p);
132	      return { path: pat, present: bytes > 0, bytes };
133	    });
134	  }
