136	  private async onVerdictLine(line: string) {
137	    for (const v of parseVerdictLines(line)) {
138	      if (v.type === "gate") {
139	        const gate = this.opts.plan?.gates.find((g) => g.id === v.gateId);
140	        const evidence = gate ? this.checkEvidence(gate) : [];
141	        let verdict: Verdict = v.verdict;
