16	export type RunEvent =
17	  | { t: number; kind: "run.start"; runId: string; mode: "plan" | "prompt"; label: string; model: string; baseUrl?: string; cwd: string }
18	  | { t: number; kind: "run.end"; runId: string; ok: boolean; reason?: string }
19	  | { t: number; kind: "plan.start"; planId: string; file: string; title?: string; gateIds: string[] }
20	  | { t: number; kind: "plan.end"; planId: string; verdict: "pass" | "fail" | "halted"; reason?: string; durationMs: number }
21	  | { t: number; kind: "session.init"; planId: string; sessionId: string; model: string; tools: string[]; cwd: string }
22	  | { t: number; kind: "session.result"; planId: string; subtype: string; costUsd: number; durationMs: number; turns: number; usage: TokenUsage; modelUsage: Record<string, { costUSD: number; inputTokens: number; outputTokens: number }> }
23	  | { t: number; kind: "assistant.text"; planId: string; text: string; parentToolUseId: string | null; final: boolean }
24	  | { t: number; kind: "assistant.delta"; planId: string; text: string; parentToolUseId: string | null }
