  1	/** Reduces RunEvents into the UI state the cockpit renders. Pure; testable. */
  2	import type { RunEvent, Verdict, TokenUsage } from "../engine/events.js";
  3	
  4	export interface ToolCard { id: string; name: string; input: unknown; summary: string; startedAt: number; endedAt?: number; ok?: boolean; tail: string; output: string; parentId: string | null; }
  5	export interface GateView { id: string; kind: string; verdict: Verdict; reason?: string; startedAt?: number; endedAt?: number; evidence: { path: string; present: boolean; bytes: number }[]; }
  6	export interface PlanView { id: string; title: string; verdict: "pending" | "running" | "pass" | "fail" | "halted"; startedAt?: number; endedAt?: number; gates: GateView[]; }
  7	export interface DiagRow { t: number; source: string; level: "debug" | "info" | "warn" | "error"; text: string; }
  8	export interface StreamBlock { kind: "text" | "tool"; id: string; parentId: string | null; text?: string; }
  9	
 10	export interface UIState {
 11	  runId: string; label: string; model: string; baseUrl?: string; cwd: string; mode: "plan" | "prompt";
 12	  startedAt: number; endedAt?: number; ok?: boolean; endReason?: string;
 13	  plans: PlanView[]; activePlan?: string;
 14	  stream: StreamBlock[]; tools: Record<string, ToolCard>; toolOrder: string[];
 15	  toolCounts: Record<string, number>; latencies: number[];
 16	  diag: DiagRow[];
 17	  costUsd: number; usage: TokenUsage; turns: number; modelUsage: Record<string, { costUSD: number; inputTokens: number; outputTokens: number }>;
 18	  pendingApproval?: { requestId: string; tool: string; input: unknown };
 19	  paused: boolean; probes: Record<string, { ok: boolean; detail: string; t: number }>;
 20	  hookCounts: { allow: number; deny: number; warn: number };
 21	  sessionId?: string;
 22	}
 23	
 24	export const MAX_DIAG = 400;
 25	export const MAX_STREAM = 600;
 26	
 27	export function initialState(): UIState {
 28	  return { runId: "", label: "", model: "", cwd: "", mode: "plan", startedAt: Date.now(), plans: [], stream: [], tools: {}, toolOrder: [], toolCounts: {}, latencies: [], diag: [], costUsd: 0, usage: { input: 0, output: 0, cacheRead: 0, cacheCreate: 0 }, turns: 0, modelUsage: {}, paused: false, probes: {}, hookCounts: { allow: 0, deny: 0, warn: 0 } };
 29	}
 30	
 31	export function summarizeInput(name: string, input: unknown): string {
 32	  const o = (input ?? {}) as Record<string, unknown>;
 33	  const s = (v: unknown) => String(v ?? "").replace(/\s+/g, " ").trim();
 34	  switch (name) {
 35	    case "Bash": return s(o.command);
 36	    case "Read": return `${s(o.file_path)}${o.offset ? ` (from line ${o.offset})` : ""}`;
 37	    case "Write": return s(o.file_path);
 38	    case "Edit": case "MultiEdit": return s(o.file_path);
 39	    case "Grep": return `${s(o.pattern)} in ${s(o.path ?? ".")}`;
 40	    case "Glob": return s(o.pattern);
 41	    case "Agent": case "Task": return `${s(o.subagent_type ?? "agent")}: ${s(o.description ?? o.prompt).slice(0, 80)}`;
 42	    default: return JSON.stringify(o).slice(0, 120);
 43	  }
 44	}
 45	
 46	function diag(state: UIState, row: DiagRow) { state.diag.push(row); if (state.diag.length > MAX_DIAG) state.diag.splice(0, state.diag.length - MAX_DIAG); }
 47	
 48	export function reduce(prev: UIState, ev: RunEvent): UIState {
 49	  const s: UIState = { ...prev };
 50	  switch (ev.kind) {
 51	    case "run.start": Object.assign(s, { runId: ev.runId, label: ev.label, model: ev.model, baseUrl: ev.baseUrl, cwd: ev.cwd, mode: ev.mode, startedAt: ev.t }); break;
 52	    case "run.end": s.endedAt = ev.t; s.ok = ev.ok; s.endReason = ev.reason; break;
 53	    case "plan.start": {
 54	      s.plans = s.plans.map((p) => p.id === ev.planId ? { ...p, verdict: "running", startedAt: ev.t } : p);
 55	      if (!s.plans.some((p) => p.id === ev.planId)) s.plans = [...s.plans, { id: ev.planId, title: ev.title ?? ev.file, verdict: "running", startedAt: ev.t, gates: ev.gateIds.map((id) => ({ id, kind: id.includes("PHASE") ? "phase" : id.includes("REGRESS") ? "regression" : "validation", verdict: "pending", evidence: [] })) }];
 56	      s.activePlan = ev.planId; s.stream = []; s.toolOrder = []; s.tools = {}; s.toolCounts = {}; s.latencies = [];
 57	      diag(s, { t: ev.t, source: "plan", level: "info", text: `▶ ${ev.planId} started (${ev.gateIds.length} gates)` });
 58	      break;
 59	    }
 60	    case "plan.end": s.plans = s.plans.map((p) => p.id === ev.planId ? { ...p, verdict: ev.verdict, endedAt: ev.t } : p); diag(s, { t: ev.t, source: "plan", level: ev.verdict === "pass" ? "info" : "error", text: `${ev.verdict === "pass" ? "✓" : "✗"} ${ev.planId} ${ev.verdict}${ev.reason ? " — " + ev.reason : ""}` }); break;
 61	    case "session.init": s.sessionId = ev.sessionId; s.model = ev.model || s.model; diag(s, { t: ev.t, source: "sdk", level: "info", text: `session ${ev.sessionId.slice(0, 8)} · ${ev.model} · ${ev.tools.length} tools · cwd ${ev.cwd}` }); break;
 62	    case "session.result": s.costUsd = ev.costUsd; s.usage = ev.usage; s.turns = ev.turns; s.modelUsage = ev.modelUsage; diag(s, { t: ev.t, source: "sdk", level: "info", text: `result/${ev.subtype} · ${ev.turns} turns · $${ev.costUsd.toFixed(3)} · ${(ev.durationMs / 1000).toFixed(0)}s` }); break;
 63	    case "assistant.delta": {
 64	      const last = s.stream[s.stream.length - 1];
 65	      if (last && last.kind === "text" && last.parentId === ev.parentToolUseId && !last.id.startsWith("final")) { s.stream = [...s.stream.slice(0, -1), { ...last, text: (last.text ?? "") + ev.text }]; }
 66	      else s.stream = [...s.stream, { kind: "text", id: `d${ev.t}${Math.random().toString(36).slice(2, 6)}`, parentId: ev.parentToolUseId, text: ev.text }];
 67	      break;
 68	    }
 69	    case "assistant.text": {
 70	      // replace the streamed draft (if any) with the final text
 71	      const last = s.stream[s.stream.length - 1];
 72	      if (last && last.kind === "text" && last.parentId === ev.parentToolUseId && !last.id.startsWith("final")) s.stream = [...s.stream.slice(0, -1), { kind: "text", id: `final${ev.t}`, parentId: ev.parentToolUseId, text: ev.text }];
 73	      else s.stream = [...s.stream, { kind: "text", id: `final${ev.t}${Math.random().toString(36).slice(2, 6)}`, parentId: ev.parentToolUseId, text: ev.text }];
 74	      break;
 75	    }
 76	    case "tool.start": {
 77	      const card: ToolCard = { id: ev.toolUseId, name: ev.name, input: ev.input, summary: summarizeInput(ev.name, ev.input), startedAt: ev.t, tail: "", output: "", parentId: ev.parentToolUseId };
 78	      s.tools = { ...s.tools, [ev.toolUseId]: card }; s.toolOrder = [...s.toolOrder, ev.toolUseId];
 79	      s.toolCounts = { ...s.toolCounts, [ev.name]: (s.toolCounts[ev.name] ?? 0) + 1 };
 80	      s.stream = [...s.stream, { kind: "tool", id: ev.toolUseId, parentId: ev.parentToolUseId }];
 81	      break;
 82	    }
 83	    case "tool.output": { const c = s.tools[ev.toolUseId]; if (c) s.tools = { ...s.tools, [ev.toolUseId]: { ...c, output: (c.output + ev.chunk).slice(-200000), tail: (c.tail + ev.chunk).split("\n").slice(-6).join("\n").slice(-600) } }; break; }
 84	    case "tool.end": { const c = s.tools[ev.toolUseId]; if (c) { s.tools = { ...s.tools, [ev.toolUseId]: { ...c, endedAt: ev.t, ok: ev.ok, output: c.output || ev.output } }; s.latencies = [...s.latencies, ev.durationMs].slice(-60); } break; }
 85	    case "hook": {
 86	      s.hookCounts = { ...s.hookCounts, [ev.decision === "observe" ? "allow" : ev.decision]: s.hookCounts[ev.decision === "observe" ? "allow" : ev.decision] + (ev.decision === "observe" ? 0 : 1) };
 87	      if (ev.decision !== "observe") diag(s, { t: ev.t, source: "hook", level: ev.decision === "deny" ? "error" : ev.decision === "warn" ? "warn" : "debug", text: `${ev.event} ${ev.tool ?? ""} ${ev.decision}${ev.reason ? " — " + ev.reason : ""}` });
 88	      break;
 89	    }
 90	    case "gate.update": {
 91	      s.plans = s.plans.map((p) => p.id !== ev.planId ? p : { ...p, gates: p.gates.map((g) => g.id === ev.gateId ? { ...g, verdict: ev.verdict, reason: ev.reason, evidence: ev.evidence ?? g.evidence, startedAt: g.startedAt ?? ev.t, endedAt: ev.verdict === "pass" || ev.verdict === "fail" ? ev.t : g.endedAt } : g) });
 92	      diag(s, { t: ev.t, source: "gate", level: ev.verdict === "fail" ? "error" : "info", text: `${ev.gateId} → ${ev.verdict.toUpperCase()}${ev.reason ? " — " + ev.reason : ""}${ev.evidence?.length ? ` · evidence ${ev.evidence.filter((e) => e.present).length}/${ev.evidence.length}` : ""}` });
 93	      break;
 94	    }
 95	    case "approval.request": s.pendingApproval = { requestId: ev.requestId, tool: ev.tool, input: ev.input }; diag(s, { t: ev.t, source: "approval", level: "warn", text: `awaiting operator: ${ev.tool} ${summarizeInput(ev.tool, ev.input)}` }); break;
 96	    case "approval.resolve": if (s.pendingApproval?.requestId === ev.requestId) s.pendingApproval = undefined; diag(s, { t: ev.t, source: "approval", level: "info", text: `${ev.behavior} by ${ev.by}` }); break;
 97	    case "probe": s.probes = { ...s.probes, [ev.name]: { ok: ev.ok, detail: ev.detail, t: ev.t } }; if (!ev.ok) diag(s, { t: ev.t, source: "sys", level: "warn", text: `${ev.name} ✗ ${ev.detail}` }); break;
 98	    case "log": diag(s, { t: ev.t, source: ev.source, level: ev.level, text: ev.message }); break;
 99	    case "control": s.paused = ev.action === "pause" ? true : ev.action === "resume" ? false : s.paused; diag(s, { t: ev.t, source: "ctl", level: "info", text: `${ev.action}${ev.detail ? ": " + ev.detail.slice(0, 120) : ""}` }); break;
100	  }
101	  if (s.stream.length > MAX_STREAM) s.stream = s.stream.slice(-MAX_STREAM);
102	  return s;
103	}
