 1	/**
 2	 * Writes <phase>-VALIDATION.md from observed gate records and updates the
 3	 * Status table in ROADMAP.md. Generated from Vigil's own observations, not
 4	 * from the agent's prose.
 5	 */
 6	import { readFileSync, writeFileSync, existsSync } from "node:fs";
 7	import { join } from "node:path";
 8	import type { GateRecord } from "../engine/store.js";
 9	import type { PlanModel } from "./parser.js";
10	
11	export function renderValidation(plans: PlanModel[], gates: GateRecord[], opts: { phase: string; platform?: string; runId: string; evidenceDir: string }): string {
12	  const byId = new Map(gates.map((g) => [g.gateId, g]));
13	  const allPass = gates.length > 0 && gates.every((g) => g.verdict === "pass" || g.verdict === "skipped");
14	  const rows = plans.flatMap((p) => p.gates.map((g) => {
15	    const r = byId.get(g.id);
16	    const ev = r?.evidence?.length ? r.evidence.map((e) => `${e.present ? "✓" : "✗"} ${e.path}`).join("<br>") : "—";
17	    return `| ${g.id} | ${(r?.verdict ?? "pending").toUpperCase()} | ${ev} | ${r?.reason ?? ""} |`;
18	  }));
19	  const phaseGate = gates.find((g) => g.gateId.startsWith("VG-PHASE"));
20	  const regress = gates.find((g) => g.gateId.startsWith("VG-REGRESS"));
21	  const failures = gates.filter((g) => g.verdict === "fail").map((g) => `- ${g.gateId}: ${g.reason ?? "no reason captured"}`);
22	  return [
23	    `# Phase ${opts.phase}: Validation Report`,
24	    "",
25	    `Verdict: ${allPass ? "PASS" : "FAIL"}`,
26	    `Date: ${new Date().toISOString()}`,
27	    `Platform: ${opts.platform ?? "full-stack"}`,
28	    `Run: ${opts.runId}`,
29	    "",
30	    "## Task Gates",
31	    "| Gate | Verdict | Evidence | Finding |",
32	    "|------|---------|----------|---------|",
33	    ...rows,
34	    "",
35	    "## Phase Gate",
36	    "| Check | Verdict | Evidence |",
37	    "|-------|---------|----------|",
38	    `| Integration | ${(phaseGate?.verdict ?? "pending").toUpperCase()} | ${phaseGate?.evidence.map((e) => e.path).join(", ") || "—"} |`,
39	    `| Regression | ${regress ? regress.verdict.toUpperCase() : "N/A"} | ${regress?.evidence.map((e) => e.path).join(", ") || "—"} |`,
40	    "",
41	    "## Evidence Files",
42	    ...[...new Set(gates.flatMap((g) => g.evidence.filter((e) => e.present).map((e) => e.path)))].map((p) => `- ${opts.evidenceDir}/${p}`),
43	    `- runs/${opts.runId}/events.jsonl`,
44	    "",
45	    "## Failures",
46	    ...(failures.length ? failures : ["None"]),
47	    "",
48	    "## Mock Violations",
49	    "None observed (rails: no denied tool calls recorded in events.jsonl with reason 'mock')",
50	    "",
51	  ].join("\n");
52	}
53	
54	export function updateRoadmapStatus(roadmapPath: string, phaseNumber: string, status: "◐ In progress" | "✓ Validated" | "✗ Failed", gate: string, evidence: string): boolean {
55	  if (!existsSync(roadmapPath)) return false;
56	  const md = readFileSync(roadmapPath, "utf8");
57	  const re = new RegExp(`^(\\|\\s*${phaseNumber}\\s*\\|)[^\\n]*$`, "m");
58	  if (!re.test(md)) return false;
59	  const next = md.replace(re, `$1 ${status} | ${gate} | ${evidence} |`);
60	  writeFileSync(roadmapPath, next);
61	  return true;
62	}
63	
64	export function validationPath(phaseDir: string, phase: string): string { return join(phaseDir, `${phase.split("-")[0]}-VALIDATION.md`); }
