 83	    case "plan.start": return `${ts} ▶ plan ${ev.planId} gates=[${ev.gateIds.join(",")}]`;
 84	    case "plan.end": return `${ts} ${ev.verdict === "pass" ? "✓" : "✗"} plan ${ev.planId} ${ev.verdict}${ev.reason ? " — " + ev.reason : ""} (${Math.round(ev.durationMs / 1000)}s)`;
 85	    case "session.init": return `${ts} session ${ev.sessionId} model=${ev.model}`;
 86	    case "session.result": return `${ts} result/${ev.subtype} turns=${ev.turns} cost=$${ev.costUsd.toFixed(3)}`;
 87	    case "assistant.text": return ev.text.split("\n").filter((l) => l.trim()).map((l) => `${ts} ▍ ${l}`).join("\n");
 88	    case "tool.start": return `${ts} ⚙ ${ev.name} ${JSON.stringify(ev.input).slice(0, 160)}`;
 89	    case "tool.end": return `${ts}   └ ${ev.ok ? "ok" : "ERROR"} ${Math.round(ev.durationMs / 1000)}s ${ev.output.split("\n").slice(-1)[0]?.slice(0, 120) ?? ""}`;
 90	    case "hook": return ev.decision === "observe" || ev.decision === "allow" ? null : `${ts} hook ${ev.event} ${ev.tool} ${ev.decision} — ${ev.reason}`;
