 92	    case "probe": return ev.ok ? null : `${ts} probe ${ev.name} ✗ ${ev.detail}`;
 93	    case "log": return ev.level === "debug" ? null : `${ts} ${ev.level} ${ev.source}: ${ev.message}`;
 94	    case "control": return `${ts} ctl ${ev.action}${ev.detail ? ": " + ev.detail.slice(0, 100) : ""}`;
 95	    case "run.end": return `${ts} run ${ev.ok ? "PASS" : "FAIL"}${ev.reason ? " — " + ev.reason : ""}`;
